# brute force all mono rectangles per quadrant
def allmono(q):
    out=[]
    for c in np.unique(q):
        m=(q==c); H,W=m.shape
        for i in range(H):
            for j in range(W):
                if not m[i,j]: continue
                for hh in range(1,H-i+1):
